// Find the earliest Friday the 13th in the proleptic Gregorian calendar (from 0001-01-01)
// and count all Friday the 13ths in a full 400-year cycle.

// --- Earliest Friday the 13th ---
var date = new DateTime(1, 1, 13); // start on the 13th of January, year 1
while (date.DayOfWeek != DayOfWeek.Friday)
    date = date.AddMonths(1);

Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd} ({date:dddd})");

// --- Count in a full 400-year cycle (the Gregorian calendar repeats every 400 years) ---
int count = 0;
var start = new DateTime(1, 1, 13);
var end = new DateTime(401, 1, 1);

var d = start;
while (d < end)
{
    if (d.DayOfWeek == DayOfWeek.Friday)
        count++;
    d = d.AddMonths(1);
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle (0001–0400): {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// --- Bonus: breakdown by day of week for the 13th ---
Console.WriteLine("\nDay-of-week distribution for the 13th (400-year cycle):");
var buckets = new int[7];
d = start;
while (d < end)
{
    buckets[(int)d.DayOfWeek]++;
    d = d.AddMonths(1);
}

foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {dow,-10} {buckets[(int)dow],4}  ({buckets[(int)dow] / 4800.0 * 100:F2}%)");

